obligations.behavior:
In 'dispose by plugin', the pinned source checks: expect(fiber.getEffects()).to.deep.equal([
{ label: 'test', children: [] },
])

In 'dispose manually', the pinned source checks: expect(root.fiber.getEffects()).to.deep.equal([
{ label: 'anonymous', children: [] },
])

In 'yield dispose', the pinned source checks: expect(root.fiber.getEffects()).to.deep.equal([
{
label: 'anonymous',
children: [
// only root level anonymous effects are included
{ label: 'ctx.on("custom-event")', children: [] },
{
label: 'anonymous',
children: [
{ label: 'ctx.on("custom-event")', children: [] },
],
},
],
},
{ label: 'ctx.on("custom-event")', children: [] },
])

In 'return with error', the pinned source checks: expect(() => {
root.effect(() => {
throw new Error('test')
return () => seq.push(1)
})
}).to.throw('test')

In 'yield with error', the pinned source checks: expect(() => {
root.effect(function* () {
yield () => seq.push(1)
throw new Error('test')
yield () => seq.push(2)
})
}).to.throw('test')
